inline const char* MsgStr(MSGSTRINGID id)
{
	if (g_multiLang && *(s_msgStrings[id]) != '/' && strcmp(s_msgStrings[id], "NO MSG") != 0)
	{
		static std::vector<std::string> s_multimsgStringTable(MSI_LAST);
		if (s_multimsgStringTable[id].empty())
		{
			static char buff[MAX_PATH];
			if (g_serviceType == ServiceAustralia && id == MSI_CANT_MAKE_CHAT_ROOM)
				sprintf(buff, "%s", s_msgStrings[id]);
			else
				sprintf(buff, "%s%s", g_language->GetLanguageCharset(true), s_msgStrings[id]);
			s_multimsgStringTable[id] = buff;
		}
		return s_multimsgStringTable[id].c_str();
	}
	return s_msgStrings[id];
}





const char* MsgStrToCompare(MSGSTRINGID id)
{
	return s_msgStrings[id];
}



bool IsEventAID(DWORD Aid)
{
	if (g_serviceType != ServiceKorea)
		return false;
	switch (Aid) {
	case 0x2c8c7d:
	case 0x2c8c7e:
	case 0x2c8c7f:
	case 0x2c8c80:
	case 0x2c8c82:
		return true;
	default:
		return false;
	}
}




const char* GetMsgString(MSGSTRINGID id)
{
	if (id < s_msgStringTable.size()) {
		return s_msgStringTable[id];
	}
	Trace("\xb4\xd9\xc0\xbd \xc7\xd1\xb1\xdb \xb8\xde\xbd\xc3\xc1\xf6\xbf\xa1 \xc7\xd8\xb4\xe7\xc7\xcf\xb4\xc2 \xb9\xf8\xbf\xaa \xbd\xba\xc5\xa9\xb8\xb3\xc6\xae\xb0\xa1 \xbe\xf8\xbd\xc0\xb4\xcf\xb4\xd9.\n ID:%d,\xb8\xde\xbd\xc3\xc1\xf6\xb8\xed:%s",
		  id, g_idMsgStrings[id].msg);
	return "NO MSG";
}







extern const char* MsgStr(MSGSTRINGID id);




void InitMsgStrings()
{

	if (g_serviceType == ServiceKorea) {
		for (int i = 0; i < sizeof(g_idMsgStrings) / sizeof(IdMsgString); i++) {
			sAssert(g_idMsgStrings[i].id == i);
			s_msgStrings[i] = g_idMsgStrings[i].msg;
		}
	} else {
		s_obj.TokenFileToPCharList(s_msgStringTable, "msgStringTable.txt", 0);
		for (int i = 0; i < sizeof(g_idMsgStrings) / sizeof(IdMsgString); i++)
			s_msgStrings[i] = GetMsgString((MSGSTRINGID)i);
	}

}








extern CSkinMgr g_skinMgr;
extern CModeMgr g_modeMgr;

const char* UIBmp(const char* uiBmpName)
{
	if (g_skinMgr.GetNumSkin() && g_skinMgr.GetCurrentSkinNum() != -1 && g_modeMgr.GetGameMode()) {
		std::string skinFolder = g_skinMgr.GetSkinCurrentFolderName();

		static std::string skinRName;
		std::string tmpName = uiBmpName;

		skinRName = "";
		for (int i = 0; i < tmpName.size() - 15; ++i) {
			skinRName += tmpName[15 + i];
		}

		g_skinMgr.ExtractFilesIfZipSkin();
		skinRName = skinFolder + skinRName;
		tmpName = skinRName;
		if (g_resMgr().IsExist(tmpName.c_str()))
			return skinRName.c_str();
	}

	if (g_serviceType == ServiceKorea)
		return uiBmpName;
	if (g_resMgr().IsExist(g_language->LanguageFile(uiBmpName)))
		return g_language->LanguageFile(uiBmpName);

	static std::string rName;
	std::string tmpName = uiBmpName;

	rName = "";
	for (int i = 0; i < tmpName.size() - 15; ++i) {
		rName += tmpName[15 + i];
	}
	rName = "UI\\" + rName;
	tmpName = rName;
	if (g_resMgr().IsExist(tmpName.c_str()))
		return rName.c_str();
	return uiBmpName;
}




char* DataTxtDecode(char* str)
{
	if (g_serviceType == ServiceKorea) {
		BYTE c;
		int len = strlen(str);
		for (int i = 0; i < len; ++i) {
			c = str[i];

			if (c >= 'a' && c <= 'z')
				c = 'a' + 'z' - c;
			if (c >= 'A' && c <= 'Z')
				c = 'A' + 'Z' - c;
			else {
				if (c >= 0xb0 && c <= 0xbf)
					c = 0xb0 + (0xbf - c);
			}
			str[i] = c;
		}
	}
	return str;
}
